using System;using System.IO;using System.Drawing;using System.Drawing.Drawing2D;using System.Drawing.Imaging;using System.Collections.Generic;
class IconBuild {
 static GraphicsPath Rounded(float x,float y,float w,float h,float r){var p=new GraphicsPath();p.AddArc(x,y,r,r,180,90);p.AddArc(x+w-r,y,r,r,270,90);p.AddArc(x+w-r,y+h-r,r,r,0,90);p.AddArc(x,y+h-r,r,r,90,90);p.CloseFigure();return p;}
 static void Main(string[] args){string dir=args[0];Directory.CreateDirectory(dir);var data=new List<byte[]>();int[] sizes={16,24,32,48,64,128,256};foreach(int size in sizes){using(var b=new Bitmap(size,size)){using(var g=Graphics.FromImage(b)){g.SmoothingMode=SmoothingMode.AntiAlias;g.ScaleTransform(size/256f,size/256f);using(var bg=new SolidBrush(Color.FromArgb(21,24,26)))using(var path=Rounded(0,0,256,256,58))g.FillPath(bg,path);using(var pen=new Pen(Color.FromArgb(118,185,0),18)){pen.StartCap=LineCap.Square;pen.EndCap=LineCap.Square;g.DrawLines(pen,new[]{new Point(62,112),new Point(62,62),new Point(112,62)});g.DrawLines(pen,new[]{new Point(194,144),new Point(194,194),new Point(144,194)});}using(var pen=new Pen(Color.FromArgb(238,242,232),18))g.DrawLine(pen,101,155,155,101);using(var brush=new SolidBrush(Color.FromArgb(118,185,0)))g.FillRectangle(brush,168,57,27,27);}using(var m=new MemoryStream()){b.Save(m,ImageFormat.Png);data.Add(m.ToArray());}if(size==256)b.Save(Path.Combine(dir,"Priint.png"),ImageFormat.Png);}}using(var w=new BinaryWriter(File.Create(Path.Combine(dir,"Priint.ico")))){w.Write((ushort)0);w.Write((ushort)1);w.Write((ushort)sizes.Length);int offset=6+16*sizes.Length;for(int i=0;i<sizes.Length;i++){w.Write((byte)(sizes[i]==256?0:sizes[i]));w.Write((byte)(sizes[i]==256?0:sizes[i]));w.Write((byte)0);w.Write((byte)0);w.Write((ushort)1);w.Write((ushort)32);w.Write(data[i].Length);w.Write(offset);offset+=data[i].Length;}foreach(var b in data)w.Write(b);}}
}
